  t0:['IDENTITY','ตัวตน'],t1:['ORIGIN','ต้นกำเนิด'],t2:['POWER','พลัง'],t3:['SKILLS','ทักษะ'],t4:['FATE','โชคชะตา'],
  l_name:['Name','ชื่อ'],l_alias:['Alias / Nickname','ฉายา'],
  l_age:['Age','อายุ'],l_gender:['Gender','เพศ'],
  l_appearance:['Physical Appearance','รูปลักษณ์'],l_personality:['Personality','บุคลิกภาพ'],
  l_faction:['Faction','สังกัด'],l_rank:['Corps Rank','ยศ'],
  l_origin_how:['Path to Corps','เส้นทางสู่กองทหาร'],
  l_region:['Region / Territory','ภูมิภาค'],
  l_dem_tier:['Power Tier','ระดับพลัง'],l_dem_origin:['How Turned','การกลายเป็นอสูร'],
  l_dem_time:['Time as Demon','ระยะเวลาเป็นอสูร'],
  l_background:['Background / History','ภูมิหลัง'],
  sh_stats:['Combat Parameters','พารามิเตอร์การต่อสู้'],
  sh_stats_note:['— click ticks','— คลิกเพื่อตั้งค่า'],
  sh_breath:['Breathing Style','สไตล์การหายใจ'],
  l_breath:['Primary Style','สไตล์หลัก'],
  l_breath_forms:['Mastered Forms / Techniques','รูปแบบที่เชี่ยวชาญ'],
  l_nichirin:['Nichirin Blade Colour','สีใบมีด'],
  sh_art:['Blood Demon Art (血鬼術)','ศิลปะเลือดอสูร (血鬼術)'],
  l_art_name:['Art Name','ชื่อศิลปะ'],l_art_desc:['Art Description','คำอธิบาย'],
  l_art_weakness:['Known Weaknesses','จุดอ่อน'],
  l_goal:['Primary Goal','เป้าหมายหลัก'],l_fate:['Narrative Fate','ชะตากรรม'],
  l_bond:['Most Important Bond','สิ่งที่ต่อสู้เพื่อ'],
  l_quote:['Their Words','คำพูดประจำตัว'],l_secret:['Hidden Truth','ความจริงที่ซ่อน'],
  l_extra:['Additional Notes','หมายเหตุ'],
  btn_confirm:['⟐ CONFIRM PATH','⟐ ยืนยันเส้นทาง'],
  btn_reset:['RESET','รีเซ็ต']
};

function g(id){return document.getElementById(id);}
function gt(k){var a=L[k];return a?a[S.ln==='th'?1:0]:k;}

/* ── INIT ── */
function init(){
  buildStats();buildSkillGrid();applyLabels();
  // custom panel toggles
  var selMap={
    's_origin_how':'cpnl_origin_how',
    's_dem_origin':'cpnl_dem_origin',
    's_goal':'cpnl_goal',
    's_breath':'cpnl_breath'
  };
  Object.keys(selMap).forEach(function(sid){
    var el=g(sid);if(!el)return;
    el.addEventListener('change',function(){
      var vis=this.value==='custom';
      var pnl=g(selMap[sid]);if(pnl)pnl.classList.toggle('vis',vis);
    });
  });
}

/* ── FACTION CHANGE ── */
function onFaction(){
  var v=g('s_faction').value;
  S.faction=v;
  var fi=FI[v]||'';
  var fib=g('faction_info');
  if(fib){fib.textContent=fi;fib.classList.toggle('vis',!!fi);}

  var badge=g('hbadge');
  if(badge){
    if(v==='Demon Slayer Corps'){
      badge.textContent='DEMON SLAYER CORPS';
      badge.style.color='#70d888';badge.style.borderColor='rgba(80,180,100,.4)';badge.style.background='rgba(80,180,100,.08)';
    } else if(v==='Demon'){
      badge.textContent='DEMON';
      badge.style.color='#e86070';badge.style.borderColor='rgba(200,48,64,.4)';badge.style.background='rgba(200,48,64,.08)';
    } else if(v){
      badge.textContent=v.toUpperCase();
      badge.style.color='#4a7fd4';badge.style.borderColor='rgba(74,127,212,.3)';badge.style.background='rgba(74,127,212,.08)';
    } else {
      badge.textContent='SELECT YOUR FACTION';
      badge.style.color='';badge.style.borderColor='';badge.style.background='';
    }
  }

  // show/hide faction sections
  var isSlayer=(v==='Demon Slayer Corps'||v==='Former Slayer');
  var isDemon=(v==='Demon');
  ['fsec_slayer'].forEach(function(id){var e=g(id);if(e)e.classList.toggle('vis',isSlayer);});
  ['fsec_breath'].forEach(function(id){var e=g(id);if(e)e.classList.toggle('vis',isSlayer);});
  ['fsec_demon'].forEach(function(id){var e=g(id);if(e)e.classList.toggle('vis',isDemon);});
  ['fsec_art'].forEach(function(id){var e=g(id);if(e)e.classList.toggle('vis',isDemon);});

  // update skill locks
  updateSkillLocks();
}

/* ── BREATHING CHANGE ── */
function onBreath(){
  var v=g('s_breath').value;
  var info=BL[v]||'';
  var ib=g('breath_info');
  if(ib){ib.textContent=info;ib.classList.toggle('vis',!!info&&v!=='custom');}
}

/* ── SKILL GRID ── */
function buildSkillGrid(){
  var grid=g('sk_grid');if(!grid)return;
  grid.innerHTML='';
  SKILLS.forEach(function(sk){
    var card=document.createElement('div');
    card.className='sk-card';
    card.id='skc_'+sk.id;
    card.setAttribute('data-tag',sk.tag);
    card.setAttribute('data-name',sk.name.toLowerCase());

    var tagClass={'uni':'t-uni','sla':'t-sla','dem':'t-dem'}[sk.tag]||'t-uni';
    var tagLabel={'uni':'✦ Universal','sla':'🗡 Slayer','dem':'👹 Demon'}[sk.tag]||'Universal';

    card.innerHTML=
      '<div class="sk-name">'+escH(sk.name)+'</div>'+
      '<div class="sk-desc">'+escH(sk.desc)+'</div>'+
      '<div class="sk-foot">'+
        '<span class="sk-tag '+tagClass+'">'+tagLabel+'</span>'+
        (sk.restrict?'<span class="sk-restrict">⚠ '+escH(sk.restrict)+'</span>':'')+
      '</div>';

    card.onclick=function(){toggleSkill(sk.id,card);};
    grid.appendChild(card);
  });
  updateSkillLocks();
  updateCount();
}

function toggleSkill(id,card){
  if(card.classList.contains('locked'))return;
  card.classList.toggle('sel');
  var i=S.skills.indexOf(id);
  if(i>=0)S.skills.splice(i,1);else S.skills.push(id);
  updateCount();
  if(S.filter==='sel')applyFilter();
}

function updateSkillLocks(){
  var isSlayer=(S.faction==='Demon Slayer Corps'||S.faction==='Former Slayer');
  var isDemon=(S.faction==='Demon');
  SKILLS.forEach(function(sk){
    var card=g('skc_'+sk.id);if(!card)return;
    var locked=false;
    if(sk.tag==='sla'&&isDemon)locked=true;
    if(sk.tag==='dem'&&isSlayer)locked=true;
    card.classList.toggle('locked',locked);
    if(locked&&card.classList.contains('sel')){
      card.classList.remove('sel');
      var i=S.skills.indexOf(sk.id);if(i>=0)S.skills.splice(i,1);
    }
  });
  updateCount();
}

function updateCount(){
  var el=g('sk_count');
  if(el)el.textContent=S.skills.length+(S.ln==='th'?' ทักษะที่เลือก':' skill'+(S.skills.length!==1?'s':'')+' selected');
}

/* ── FILTER ── */
function sf(f){
  S.filter=f;
  document.querySelectorAll('.sk-filter').forEach(function(b){b.classList.toggle('on',b.getAttribute('data-f')===f);});
  applyFilter();
}

function applyFilter(){
  var q=S.search.toLowerCase();
  SKILLS.forEach(function(sk){
    var card=g('skc_'+sk.id);if(!card)return;
    var show=true;
    if(S.filter==='uni'&&sk.tag!=='uni')show=false;
    if(S.filter==='sla'&&sk.tag!=='sla')show=false;
    if(S.filter==='dem'&&sk.tag!=='dem')show=false;
    if(S.filter==='sel'&&!card.classList.contains('sel'))show=false;
    if(q&&card.getAttribute('data-name').indexOf(q)<0&&sk.desc.toLowerCase().indexOf(q)<0)show=false;
    card.classList.toggle('hidden',!show);
  });
}

function search(){
  S.search=(g('sk_search').value||'').trim();
  applyFilter();
}

/* ── STATS ── */
function buildStats(){
  var TH=S.ln==='th',blk=g('stat_block');
  if(!blk)return;blk.innerHTML='';
  STATS.forEach(function(st){
    var key=st[0],nm=TH?st[2]:st[1];
    var row=document.createElement('div');row.className='stat-row';
    var nd=document.createElement('div');nd.className='stat-nm';nd.textContent=nm;
    var td=document.createElement('div');td.className='ticks';td.id='tck_'+key;
    var vd=document.createElement('div');vd.className='stat-v';vd.id='sv_'+key;
    for(var i=1;i<=10;i++){
      (function(i){
        var t=document.createElement('div');
        t.className='tick'+(S.stats[key]>=i?' on':'')+(i>=9&&S.stats[key]>=i?' hi':'');
        t.onclick=function(){setStat(key,i);};
        td.appendChild(t);
      })(i);
    }
    vd.textContent=S.stats[key];
    row.appendChild(nd);row.appendChild(td);row.appendChild(vd);
    blk.appendChild(row);
  });
}
function setStat(key,val){
  S.stats[key]=val;
  var tc=g('tck_'+key).children;
  for(var i=0;i<10;i++){tc[i].className='tick'+(val>i?' on':'')+(i>=8&&val>i?' hi':'');}
  g('sv_'+key).textContent=val;
}

/* ── LABELS ── */
function applyLabels(){
  ['tbar_mid','htag','htitle','hsub','t0','t1','t2','t3','t4',
   'l_name','l_alias','l_age','l_gender','l_appearance','l_personality',
   'l_faction','l_rank','l_origin_how','l_region',
   'l_dem_tier','l_dem_origin','l_dem_time','l_background',
   'sh_stats','sh_stats_note','sh_breath','l_breath','l_breath_forms','l_nichirin',
   'sh_art','l_art_name','l_art_desc','l_art_weakness',
   'l_goal','l_fate','l_bond','l_quote','l_secret','l_extra'
  ].forEach(function(k){var el=g(k);if(el)el.textContent=gt(k);});
  g('btn_confirm').textContent=gt('btn_confirm');
  g('btn_reset').textContent=gt('btn_reset');
  buildStats();updateCount();
}

/* ── TABS ── */
function tb(i){
  document.querySelectorAll('.spane').forEach(function(p,j){p.classList.toggle('on',j===i);});
  document.querySelectorAll('.stab').forEach(function(t,j){t.classList.toggle('on',j===i);});
}

/* ── LANGUAGE ── */
function ln(m){
  S.ln=m;
  g('btn_en').classList.toggle('on',m==='en');
  g('btn_th').classList.toggle('on',m==='th');
  applyLabels();
}

/* ── CUSTOM PANEL ── */
function tc(key){var el=g('cpnl_'+key);if(el)el.classList.toggle('vis');}

/* ── ESCAPE ── */
function escH(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

/* ── RESET ── */
function reset(){
  S.skills=[];S.stats={str:5,spd:5,stm:5,int:5,wil:5,sen:5};S.faction='';S.filter='all';S.search='';
  document.querySelectorAll('.finp,.fsel,.farea').forEach(function(el){
    if(el.tagName==='SELECT')el.selectedIndex=0;else el.value='';
  });
  document.querySelectorAll('.cpnl,.infoblurb,.fsec').forEach(function(el){el.classList.remove('vis');});
  document.querySelectorAll('.sk-card.sel').forEach(function(c){c.classList.remove('sel');});
  document.querySelectorAll('.sk-card.hidden').forEach(function(c){c.classList.remove('hidden');});
  document.querySelectorAll('.sk-card.locked').forEach(function(c){c.classList.remove('locked');});
  var sd=g('sk_search');if(sd)sd.value='';
  sf('all');
  var badge=g('hbadge');
  if(badge){badge.textContent='SELECT YOUR FACTION';badge.style.color='';badge.style.borderColor='';badge.style.background='';}
  buildStats();tb(0);
}

/* ── SEND ── */
function send(){
  var v=function(id){var el=g(id);return el?el.value.trim():'';};
  var cv=function(sid,cid){return v(sid)==='custom'?v(cid):v(sid);};

  var skNames=SKILLS.filter(function(sk){return S.skills.indexOf(sk.id)>=0;}).map(function(sk){return sk.name;});

  var out={
    lang:S.ln,
    name:v('s_name'),alias:v('s_alias'),age:v('s_age'),gender:v('s_gender'),
    appearance:v('s_appearance'),personality:v('s_personality'),
    faction:v('s_faction'),
    rank:v('s_rank'),
    origin_path:cv('s_origin_how','s_origin_how_c'),
    region:v('s_region'),
    demon_tier:v('s_dem_tier'),
    demon_origin:cv('s_dem_origin','s_dem_origin_c'),
    demon_time:v('s_dem_time'),
    background:v('s_background'),
    breathing_style:v('s_breath')==='custom'?v('s_breath_c'):v('s_breath'),
    breathing_forms:v('s_breath_forms'),
    nichirin_colour:v('s_nichirin'),
    blood_demon_art:v('s_art_name'),
    blood_demon_art_desc:v('s_art_desc'),
    blood_demon_art_weakness:v('s_art_weakness'),
    stats:S.stats,
    skills:skNames,
    goal:cv('s_goal','s_goal_c'),
    fate:v('s_fate'),
    bond:v('s_bond'),
    quote:v('s_quote'),
    secret:v('s_secret'),
    extra:v('s_extra')
  };

  var txt='<'+'KNY_CONFIRM>'+JSON.stringify(out,null,2)+'<'+'/KNY_CONFIRM>';
  setTimeout(function(){
    try{
      var w=window.parent||window;
      var ta=w.document.getElementById('send_textarea')||w.document.querySelector('textarea.chat-input,#textareaAutosize,textarea');
      if(ta){
        var d=Object.getOwnPropertyDescriptor(w.HTMLTextAreaElement.prototype,'value');
        if(d&&d.set)d.set.call(ta,txt);else ta.value=txt;
        ta.dispatchEvent(new Event('input',{bubbles:true}));
        setTimeout(function(){
          try{
            var sb=w.document.getElementById('send_but');
            if(sb)sb.click();
            else ta.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',keyCode:13,bubbles:true}));
          }catch(e){}
        },150);
        return;
      }
    }catch(e){}
    try{navigator.clipboard.writeText(txt);}catch(e){}
  },450);
}

return{init:init,ln:ln,tb:tb,tc:tc,send:send,reset:reset,onFaction:onFaction,onBreath:onBreath,sf:sf,search:search};
})();
window.addEventListener('DOMContentLoaded',KNY.init);
</script>
</body>
</html>

